      {...props}
    >
      <rect x="3.5" y="8" width="17" height="10" rx="1.5" /><circle cx="8.5" cy="13" r="2.5" /><circle cx="15.5" cy="13" r="2.5" /><path d="M6 8 9 4.5M18 8l-3-3.5" />
